  1	import { and, eq, inArray, isNull, sql } from "drizzle-orm";
  2	import {
  3	  db,
  4	  workspaces,
  5	  workspaceMembers,
  6	  projects,
  7	  appUsers,
  8	  type Workspace,
  9	} from "@workspace/db";
 10	import { ensureUniqueSlug, slugify } from "./slug";
 11	
 12	function isUniqueViolation(err: unknown): boolean {
 13	  return Boolean(err && typeof err === "object" && (err as { code?: string }).code === "23505");
 14	}
 15	
 16	export async function ensurePersonalWorkspace(userId: number): Promise<Workspace> {
 17	  const [user] = await db.select().from(appUsers).where(eq(appUsers.id, userId));
 18	
 19	  // Fast path: a personal workspace already exists for this user.
 20	  const [existing] = await db
 21	    .select()
 22	    .from(workspaces)
 23	    .where(and(eq(workspaces.ownerUserId, userId), eq(workspaces.isPersonal, 1)));
 24	
 25	  let ws: Workspace;
 26	  if (existing) {
 27	    ws = existing;
 28	  } else {
 29	    // Race-safe create: rely on the partial-unique index (one personal ws per owner).
 30	    const display = user?.firstName ? `${user.firstName}'s workspace` : "Personal workspace";
 31	    const baseSlugRoot = user?.firstName ? slugify(user.firstName) : `personal-${userId}`;
 32	    let attempt = 0;
 33	    let created: Workspace | undefined;
 34	    while (attempt < 5 && !created) {
 35	      attempt += 1;
 36	      const slug = await ensureUniqueSlug(baseSlugRoot, async (s) => {
 37	        const [hit] = await db.select({ id: workspaces.id }).from(workspaces).where(eq(workspaces.slug, s));
 38	        return Boolean(hit);
 39	      });
 40	      try {
 41	        const rows = await db
 42	          .insert(workspaces)
 43	          .values({ slug, name: display, ownerUserId: userId, isPersonal: 1 })
 44	          .returning();
 45	        created = rows[0];
 46	      } catch (err) {
 47	        if (!isUniqueViolation(err)) throw err;
 48	        // Either slug raced, or the personal-per-owner unique fired; re-check first.
 49	        const [racedExisting] = await db
 50	          .select()
 51	          .from(workspaces)
 52	          .where(and(eq(workspaces.ownerUserId, userId), eq(workspaces.isPersonal, 1)));
 53	        if (racedExisting) {
 54	          created = racedExisting;
 55	        }
 56	        // else: slug collision, loop and try a fresh slug
 57	      }
 58	    }
 59	    if (!created) throw new Error("Failed to create personal workspace after retries");
 60	    ws = created;
 61	  }
 62	
 63	  // Ensure owner member row exists.
 64	  try {
 65	    await db
 66	      .insert(workspaceMembers)
 67	      .values({
 68	        workspaceId: ws.id,
 69	        userId,
 70	        role: "owner",
 71	        status: "active",
 72	        joinedAt: new Date(),
 73	      })
 74	      .onConflictDoNothing();
 75	  } catch (err) {
 76	    if (!isUniqueViolation(err)) throw err;
 77	  }
 78	
 79	  // Migrate any of the user's projects without a workspace.
 80	  const orphans = await db
 81	    .select()
 82	    .from(projects)
 83	    .where(and(eq(projects.ownerUserId, userId), isNull(projects.workspaceId)));
 84	  for (const p of orphans) {
 85	    let attempt = 0;
 86	    while (attempt < 5) {
 87	      attempt += 1;
 88	      const slug = await ensureUniqueSlug(p.name, async (s) => {
 89	        const [hit] = await db
 90	          .select({ id: projects.id })
 91	          .from(projects)
 92	          .where(and(eq(projects.workspaceId, ws.id), eq(projects.slug, s)));
 93	        return Boolean(hit);
 94	      });
 95	      try {
 96	        await db.update(projects).set({ workspaceId: ws.id, slug }).where(eq(projects.id, p.id));
 97	        break;
 98	      } catch (err) {
 99	        if (!isUniqueViolation(err)) throw err;
100	        // raced — try a different slug
101	      }
102	    }
103	  }
104	  return ws;
105	}
106	
107	export async function listUserWorkspaces(userId: number): Promise<Workspace[]> {
108	  const memberRows = await db
109	    .select({ workspaceId: workspaceMembers.workspaceId })
110	    .from(workspaceMembers)
111	    .where(and(eq(workspaceMembers.userId, userId), eq(workspaceMembers.status, "active")));
112	  const ids = memberRows.map((r) => r.workspaceId);
113	  if (ids.length === 0) return [];
114	  const rows = await db
115	    .select()
116	    .from(workspaces)
117	    .where(inArray(workspaces.id, ids))
118	    .orderBy(sql`${workspaces.isPersonal} desc`, sql`${workspaces.createdAt} desc`);
119	  return rows;
120	}
121	
122	export async function findWorkspaceBySlug(slug: string): Promise<Workspace | null> {
123	  const [row] = await db.select().from(workspaces).where(eq(workspaces.slug, slug));
124	  return row ?? null;
125	}
126	
127	export async function userHasWorkspaceAccess(
128	  workspaceId: number,
129	  userId: number,
130	): Promise<{ access: boolean; role: string | null }> {
131	  const [row] = await db
132	    .select()
133	    .from(workspaceMembers)
134	    .where(and(eq(workspaceMembers.workspaceId, workspaceId), eq(workspaceMembers.userId, userId)));
135	  if (!row || row.status !== "active") return { access: false, role: null };
136	  return { access: true, role: row.role };
137	}
138	
139	export async function findProjectInWorkspace(
140	  workspaceId: number,
141	  projectSlug: string,
142	): Promise<{ id: number } | null> {
143	  const [row] = await db
144	    .select({ id: projects.id })
145	    .from(projects)
146	    .where(and(eq(projects.workspaceId, workspaceId), eq(projects.slug, projectSlug)));
147	  return row ?? null;
148	}
149	
150	export async function generateProjectSlug(workspaceId: number, name: string): Promise<string> {
151	  return ensureUniqueSlug(name, async (s) => {
152	    const [hit] = await db
153	      .select({ id: projects.id })
154	      .from(projects)
155	      .where(and(eq(projects.workspaceId, workspaceId), eq(projects.slug, s)));
156	    return Boolean(hit);
157	  });
158	}
159	
160	export { isUniqueViolation };

