    if (!slug) return;
    setDetailLoading(true);
    workspacesApi
      .detail(slug)
      .then((d) => setDetail(d))
      .catch((e) => toast({ title: "Workspace error", description: e instanceof Error ? e.message : String(e), variant: "destructive" }))

