    cardBox:
      "bg-[hsl(222_47%_11%)] rounded-2xl w-[440px] max-w-full overflow-hidden border border-[hsl(217_33%_25%)] shadow-2xl",
    card: "!shadow-none !border-0 !bg-transparent !rounded-none",
