  1	import { useEffect, useMemo, useRef, useState } from "react";
  2	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
  3	import { Button } from "@/components/ui/button";
  4	import { Textarea } from "@/components/ui/textarea";
  5	import { MessageSquare, Send, Sparkles, Loader2, Trash2 } from "lucide-react";
  6	
  7	type Msg = { role: "user" | "assistant"; content: string };
  8	
  9	interface LearnChatProps {
 10	  topicId: string;
 11	  topicTitle: string;
 12	  starterQuestions?: string[];
 13	}
 14	
 15	const API_BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
 16	const MAX_PERSISTED_MESSAGES = 40;
 17	
 18	function storageKey(topicId: string) {
 19	  return `gameforge.learn.chat.${topicId}`;
 20	}
 21	
 22	function isValidMsg(x: unknown): x is Msg {
 23	  if (!x || typeof x !== "object") return false;
 24	  const r = x as Record<string, unknown>;
 25	  return (r.role === "user" || r.role === "assistant") && typeof r.content === "string";
 26	}
 27	
 28	export function LearnChat({ topicId, topicTitle, starterQuestions = [] }: LearnChatProps) {
 29	  const [messages, setMessages] = useState<Msg[]>([]);
 30	  const [draft, setDraft] = useState("");
 31	  const [loading, setLoading] = useState(false);
 32	  const [error, setError] = useState<string | null>(null);
 33	  const scrollRef = useRef<HTMLDivElement>(null);
 34	
 35	  // Load persisted history per topic.
 36	  useEffect(() => {
 37	    setError(null);
 38	    setDraft("");
 39	    try {
 40	      const raw = localStorage.getItem(storageKey(topicId));
 41	      const parsed = raw ? JSON.parse(raw) : [];
 42	      if (Array.isArray(parsed)) {
 43	        setMessages(parsed.filter(isValidMsg).slice(-MAX_PERSISTED_MESSAGES));
 44	      } else {
 45	        setMessages([]);
 46	      }
 47	    } catch {
 48	      setMessages([]);
 49	    }
 50	  }, [topicId]);
 51	
 52	  useEffect(() => {
 53	    try {
 54	      const trimmed = messages.slice(-MAX_PERSISTED_MESSAGES);
 55	      localStorage.setItem(storageKey(topicId), JSON.stringify(trimmed));
 56	    } catch {/* ignore */}
 57	  }, [messages, topicId]);
 58	
 59	  useEffect(() => {
 60	    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
 61	  }, [messages, loading]);
 62	
 63	  const send = async (text: string) => {
 64	    const trimmed = text.trim();
 65	    if (!trimmed || loading) return;
 66	    const next: Msg[] = [...messages, { role: "user", content: trimmed }];
 67	    setMessages(next);
 68	    setDraft("");
 69	    setLoading(true);
 70	    setError(null);
 71	    try {
 72	      const res = await fetch(`${API_BASE}/api/learn/chat`, {
 73	        method: "POST",
 74	        credentials: "include",
 75	        headers: { "Content-Type": "application/json" },
 76	        body: JSON.stringify({
 77	          topicId,
 78	          message: trimmed,
 79	          history: messages.slice(-10),
 80	        }),
 81	      });
 82	      if (!res.ok) {
 83	        const body = await res.json().catch(() => ({}));
 84	        throw new Error(body.error || `HTTP ${res.status}`);
 85	      }
 86	      const data = (await res.json()) as { reply: string };
 87	      setMessages([...next, { role: "assistant", content: data.reply }]);
 88	    } catch (err) {
 89	      setError(err instanceof Error ? err.message : String(err));
 90	    } finally {
 91	      setLoading(false);
 92	    }
 93	  };
 94	
 95	  const clear = () => {
 96	    setMessages([]);
 97	    setError(null);
 98	    try { localStorage.removeItem(storageKey(topicId)); } catch {/* ignore */}
 99	  };
100	
101	  const showStarters = useMemo(() => messages.length === 0 && starterQuestions.length > 0, [messages, starterQuestions]);
102	
103	  return (
104	    <Card className="bg-card border-border" data-testid="learn-chat">
105	      <CardHeader className="pb-3">
106	        <div className="flex items-center justify-between gap-2">
107	          <CardTitle className="text-sm flex items-center gap-2">
108	            <MessageSquare className="h-4 w-4 text-primary" />
109	            Ask the tutor
110	          </CardTitle>
111	          {messages.length > 0 && (
112	            <Button
113	              variant="ghost"
114	              size="sm"
115	              className="h-7 px-2 text-xs text-muted-foreground hover:text-foreground gap-1"
116	              onClick={clear}
117	              data-testid="learn-chat-clear"
118	            >
119	              <Trash2 className="h-3 w-3" /> Clear
120	            </Button>
121	          )}
122	        </div>
123	        <p className="text-xs text-muted-foreground mt-1">
124	          Ask anything about <span className="text-foreground font-medium">{topicTitle}</span>.
125	          Switch chapters to ask about a different topic.
126	        </p>
127	      </CardHeader>
128	      <CardContent className="space-y-3">
129	        <div
130	          ref={scrollRef}
131	          className="max-h-[320px] overflow-y-auto space-y-2.5 pr-1"
132	          data-testid="learn-chat-thread"
133	        >
134	          {showStarters && (
135	            <div className="rounded-md border border-dashed border-border/60 p-3 space-y-2">
136	              <div className="text-xs uppercase tracking-wider text-muted-foreground flex items-center gap-1.5">
137	                <Sparkles className="h-3 w-3" /> Try asking
138	              </div>
139	              <div className="flex flex-col gap-1.5">
140	                {starterQuestions.map((q, i) => (
141	                  <button
142	                    key={i}
143	                    onClick={() => send(q)}
144	                    disabled={loading}
145	                    className="text-left text-xs rounded-md border border-border/60 bg-muted/30 hover:bg-muted/60 px-2.5 py-1.5 transition-colors disabled:opacity-50"
146	                    data-testid={`learn-chat-starter-${i}`}
147	                  >
148	                    {q}
149	                  </button>
150	                ))}
151	              </div>
152	            </div>
153	          )}
154	          {messages.map((m, i) => (
155	            <div
156	              key={i}
157	              className={`text-sm leading-relaxed rounded-md px-3 py-2 ${
158	                m.role === "user"
159	                  ? "bg-primary/10 border border-primary/30 text-foreground"
160	                  : "bg-muted/40 border border-border/60 text-foreground/90 whitespace-pre-wrap"
161	              }`}
162	            >
163	              <div className="text-[10px] uppercase tracking-wider text-muted-foreground mb-0.5">
164	                {m.role === "user" ? "You" : "Tutor"}
165	              </div>
166	              {m.content}
167	            </div>
168	          ))}
169	          {loading && (
170	            <div className="text-sm rounded-md px-3 py-2 bg-muted/40 border border-border/60 flex items-center gap-2 text-muted-foreground">
171	              <Loader2 className="h-3.5 w-3.5 animate-spin" /> Tutor is thinking…
172	            </div>
173	          )}
174	          {error && (
175	            <div className="text-xs rounded-md px-3 py-2 bg-destructive/10 border border-destructive/40 text-destructive">
176	              {error}
177	            </div>
178	          )}
179	        </div>
180	        <div className="flex items-end gap-2 pt-1">
181	          <Textarea
182	            value={draft}
183	            onChange={(e) => setDraft(e.target.value)}
184	            onKeyDown={(e) => {
185	              if (e.key === "Enter" && !e.shiftKey) {
186	                e.preventDefault();
187	                send(draft);
188	              }
189	            }}
190	            placeholder={`Ask anything about "${topicTitle}"…`}
191	            disabled={loading}
192	            className="min-h-[48px] max-h-[120px] resize-none bg-muted/30 border-border/60 text-sm"
193	            data-testid="learn-chat-input"
194	          />
195	          <Button
196	            onClick={() => send(draft)}
197	            disabled={!draft.trim() || loading}
198	            size="sm"
199	            className="h-10 gap-1.5 shrink-0"
200	            data-testid="learn-chat-send"
201	          >
202	            {loading ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Send className="h-3.5 w-3.5" />}
203	            Send
204	          </Button>
205	        </div>
206	      </CardContent>
207	    </Card>
208	  );
209	}

