  const stashReturn = () => {
    try { sessionStorage.setItem("gameforge.learn.returnTo", `/${slug}`); } catch {/* ignore */}
  };

  const biblePct = Math.round((bibleDone / BIBLE_TOTAL) * 100);
  const design101Pct = Math.round((design101Done / DESIGN101_TOTAL) * 100);

