import { Router, type IRouter } from "express";
import healthRouter from "./health";
import meRouter from "./me";
import adminRouter from "./admin";
import projectsRouter from "./projects";
import entitiesRouter from "./entities";
import propertiesRouter from "./properties";
import rulesRouter from "./rules";
import playersRouter from "./players";
import notesRouter from "./notes";
import tasksRouter from "./tasks";
import chatRouter from "./chat";
import dashboardRouter from "./dashboard";
import researchRouter from "./research";
import assetsRouter from "./assets";
import simulatorRouter from "./simulator";
import playtestRouter from "./playtest";
import publicFeedbackRouter from "./publicFeedback";
import storyboardRouter from "./storyboard";
import balanceRouter from "./balance";
import changelogRouter from "./changelog";
import exportsRouter from "./exports";
import blueprintRouter from "./blueprint";
import kickstarterRouter from "./kickstarter";
import workspacesRouter from "./workspaces";
import learnRouter from "./learn";
import aiTextRouter from "./aiText";
import snapshotsRouter from "./snapshots";
import collaborationRouter from "./collaboration";
import {
  requireAuth,
  requireProjectAccess,
} from "../middlewares/projectAuth";

const router: IRouter = Router();

// Public/unauthenticated routes
router.use(healthRouter);
router.use(publicFeedbackRouter);

// Authenticated routes
router.use(meRouter);
router.use(adminRouter);
router.use(dashboardRouter);

// Workspaces join preview is public (no auth); all other /workspaces routes require auth.
router.use("/workspaces", (req, res, next) => {
  if (req.method === "GET" && /^\/workspaces\/join\/[^/]+$/.test(req.path)) return next();
  return requireAuth(req, res, next);
});
router.use(workspacesRouter);

// Topic-scoped Learn tutor (authenticated, no project context)
router.use("/learn", requireAuth);
router.use(learnRouter);

// Projects routes (auth required, project-scoped routes have ownership/membership check)
router.use("/projects", requireAuth);
router.use("/projects/:projectId", requireProjectAccess);

router.use(projectsRouter);
router.use(researchRouter);
router.use(entitiesRouter);
router.use(propertiesRouter);
router.use(rulesRouter);
router.use(playersRouter);
router.use(notesRouter);
router.use(tasksRouter);
router.use(chatRouter);
router.use(assetsRouter);
router.use(simulatorRouter);
router.use(playtestRouter);
router.use(storyboardRouter);
router.use(balanceRouter);
router.use(changelogRouter);
router.use(exportsRouter);
router.use(blueprintRouter);
router.use(kickstarterRouter);
router.use(aiTextRouter);
router.use(snapshotsRouter);
router.use(collaborationRouter);

export default router;

import { useEffect, useRef } from "react";
import { Switch, Route, Router as WouterRouter, useLocation, Redirect } from "wouter";
import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
import { ClerkProvider, SignIn, SignUp, Show, useClerk } from "@clerk/react";
import { dark } from "@clerk/themes";
import { Toaster } from "@/components/ui/toaster";
import { TooltipProvider } from "@/components/ui/tooltip";
import NotFound from "@/pages/not-found";
import Workspace from "@/pages/workspace";
import WorkspaceHome from "@/pages/workspace-home";
import WorkspaceBySlug from "@/pages/workspace-by-slug";
import Account from "@/pages/account";
import Admin from "@/pages/admin";
import LearnPage from "@/pages/learn";
import Landing from "@/pages/landing";
import PublicFeedback from "@/pages/public-feedback";
import JoinWorkspace from "@/pages/join-workspace";

const queryClient = new QueryClient();

const clerkPubKey = import.meta.env.VITE_CLERK_PUBLISHABLE_KEY;
const clerkProxyUrl = import.meta.env.VITE_CLERK_PROXY_URL;
const basePath = import.meta.env.BASE_URL.replace(/\/$/, "");

if (!clerkPubKey) {
  throw new Error("Missing VITE_CLERK_PUBLISHABLE_KEY in environment");
}

function stripBase(path: string): string {
  return basePath && path.startsWith(basePath)
    ? path.slice(basePath.length) || "/"
    : path;
}

const clerkAppearance = {
  theme: dark,
  cssLayerName: "clerk",
  options: {
    logoPlacement: "inside" as const,
    logoLinkUrl: basePath || "/",
    logoImageUrl: `${typeof window !== "undefined" ? window.location.origin : ""}${basePath}/logo.svg`,
  },
  variables: {
    colorPrimary: "hsl(263 70% 60%)",
    colorForeground: "hsl(210 40% 98%)",
    colorMutedForeground: "hsl(215 20% 65%)",
    colorDanger: "hsl(0 84% 60%)",
    colorBackground: "hsl(222 47% 11%)",
    colorInput: "hsl(217 33% 17%)",
    colorInputForeground: "hsl(210 40% 98%)",
    colorNeutral: "hsl(217 33% 25%)",
    fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif",
    borderRadius: "0.5rem",
  },
  elements: {
    rootBox: "w-full",
    cardBox:
      "bg-[hsl(222_47%_11%)] rounded-2xl w-[440px] max-w-full overflow-hidden border border-[hsl(217_33%_25%)] shadow-2xl",
    card: "!shadow-none !border-0 !bg-transparent !rounded-none",
    footer: "!shadow-none !border-0 !bg-transparent !rounded-none",
    headerTitle: "text-white text-2xl font-bold",
    headerSubtitle: "text-slate-400",
    socialButtonsBlockButtonText: "text-white",
    formFieldLabel: "text-slate-200",
    footerActionLink: "text-violet-400 hover:text-violet-300",
    footerActionText: "text-slate-400",
    dividerText: "text-slate-400",
    identityPreviewEditButton: "text-violet-400",
    formFieldSuccessText: "text-emerald-400",
    alertText: "text-red-400",
    logoBox: "flex justify-center mb-2",
    logoImage: "h-10 w-10",
    socialButtonsBlockButton:
      "bg-[hsl(217_33%_17%)] hover:bg-[hsl(217_33%_22%)] border border-[hsl(217_33%_25%)]",
    formButtonPrimary:
      "bg-violet-600 hover:bg-violet-500 text-white font-medium",
    formFieldInput:
      "bg-[hsl(217_33%_17%)] border border-[hsl(217_33%_25%)] text-white",
    footerAction: "text-slate-400",
    dividerLine: "bg-[hsl(217_33%_25%)]",
    alert: "bg-red-950/40 border border-red-900",
    otpCodeFieldInput: "bg-[hsl(217_33%_17%)] text-white",
    formFieldRow: "",
    main: "",
  },
};

function SignInPage() {
  return (
    <div className="flex min-h-[100dvh] items-center justify-center bg-background px-4">
      <SignIn
        routing="path"
        path={`${basePath}/sign-in`}
        signUpUrl={`${basePath}/sign-up`}
      />
    </div>
  );
}

function SignUpPage() {
  return (
    <div className="flex min-h-[100dvh] items-center justify-center bg-background px-4">
      <SignUp
        routing="path"
        path={`${basePath}/sign-up`}
        signInUrl={`${basePath}/sign-in`}
      />
    </div>
  );
}

function HomeRedirect() {
  return (
    <>
      <Show when="signed-in">
        <WorkspaceHome />
      </Show>
      <Show when="signed-out">
        <Landing />
      </Show>
    </>
  );
}

const RESERVED_TOP_PATHS = new Set([
  "sign-in", "sign-up", "feedback", "account", "admin", "p", "api", "_assets", "favicon.ico", "join",
]);

function ProtectedRoute({ children }: { children: React.ReactNode }) {
  return (
    <>
      <Show when="signed-in">{children}</Show>
      <Show when="signed-out">
        <Redirect to="/" />
      </Show>
    </>
  );
}

function ClerkQueryClientCacheInvalidator() {
  const { addListener } = useClerk();
  const qc = useQueryClient();
  const prevUserIdRef = useRef<string | null | undefined>(undefined);

  useEffect(() => {
    const unsubscribe = addListener(({ user }) => {
      const userId = user?.id ?? null;
      if (
        prevUserIdRef.current !== undefined &&
        prevUserIdRef.current !== userId
      ) {
        qc.clear();
      }
      prevUserIdRef.current = userId;
    });
    return unsubscribe;
  }, [addListener, qc]);

  return null;
}

function Routes() {
  return (
    <Switch>
      <Route path="/" component={HomeRedirect} />
      <Route path="/sign-in/*?" component={SignInPage} />
      <Route path="/sign-up/*?" component={SignUpPage} />
      <Route path="/feedback/:token" component={PublicFeedback} />
      <Route path="/join/:code" component={JoinWorkspace} />
      <Route path="/account">
        <ProtectedRoute>
          <Account />
        </ProtectedRoute>
      </Route>
      <Route path="/learn">
        <ProtectedRoute>
          <LearnPage />
        </ProtectedRoute>
      </Route>
      <Route path="/admin">
        <ProtectedRoute>
          <Admin />
        </ProtectedRoute>
      </Route>
      <Route path="/p/:projectId">
        {(params) => (
          <ProtectedRoute>
            <Workspace key={params.projectId} />
          </ProtectedRoute>
        )}
      </Route>
      <Route path="/:workspaceSlug/:projectSlug">
        {(params) =>
          RESERVED_TOP_PATHS.has(params.workspaceSlug) ? (
            <NotFound />
          ) : (
            <ProtectedRoute>
              <WorkspaceBySlug key={`${params.workspaceSlug}/${params.projectSlug}`} />
            </ProtectedRoute>
          )
        }
      </Route>
      <Route path="/:workspaceSlug">
        {(params) =>
          RESERVED_TOP_PATHS.has(params.workspaceSlug) ? (
            <NotFound />
          ) : (
            <ProtectedRoute>
              <WorkspaceHome key={params.workspaceSlug} />
            </ProtectedRoute>
          )
        }
      </Route>
      <Route component={NotFound} />
    </Switch>
  );
}

function ClerkProviderWithRoutes() {
  const [, setLocation] = useLocation();
  return (
    <ClerkProvider
      publishableKey={clerkPubKey}
      proxyUrl={clerkProxyUrl}
      appearance={clerkAppearance}
      signInUrl={`${basePath}/sign-in`}
      signUpUrl={`${basePath}/sign-up`}
      localization={{
        signIn: {
          start: { title: "Welcome back to GameForge", subtitle: "Sign in to continue designing your game" },
        },
        signUp: {
          start: { title: "Join GameForge", subtitle: "Build, simulate, and ship your board game" },
        },
      }}
      routerPush={(to) => setLocation(stripBase(to))}
      routerReplace={(to) => setLocation(stripBase(to), { replace: true })}
    >
      <QueryClientProvider client={queryClient}>
        <ClerkQueryClientCacheInvalidator />
        <TooltipProvider>
          <Routes />
          <Toaster />
        </TooltipProvider>
      </QueryClientProvider>
    </ClerkProvider>
  );
}

function App() {
  return (
    <WouterRouter base={basePath}>
      <ClerkProviderWithRoutes />
    </WouterRouter>
  );
}

export default App;

import { useEffect, useState } from "react";
import { useParams, useLocation } from "wouter";
import { useUser } from "@clerk/react";
import { Gamepad2, Users, Loader2, CheckCircle2, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { workspacesApi } from "@/lib/workspaces-api";
import { Link } from "wouter";

interface WorkspacePreview {
  id: number;
  name: string;
  slug: string;
  memberCount: number;
}

export default function JoinWorkspace() {
  const { code } = useParams<{ code: string }>();
  const [, setLocation] = useLocation();
  const { isSignedIn, isLoaded } = useUser();

  const [preview, setPreview] = useState<WorkspacePreview | null>(null);
  const [previewError, setPreviewError] = useState<string | null>(null);
  const [joining, setJoining] = useState(false);
  const [joined, setJoined] = useState(false);
  const [joinError, setJoinError] = useState<string | null>(null);

  useEffect(() => {
    if (!code) return;
    workspacesApi.previewJoin(code)
      .then(setPreview)
      .catch((err) => setPreviewError(err instanceof Error ? err.message : String(err)));
  }, [code]);

  const join = async () => {
    if (!code) return;
    setJoining(true);
    setJoinError(null);
    try {
      const result = await workspacesApi.joinByCode(code);
      setJoined(true);
      setTimeout(() => setLocation(`/${result.slug}`), 1200);
    } catch (err) {
      setJoinError(err instanceof Error ? err.message : String(err));
    } finally {
      setJoining(false);
    }
  };

  return (
    <div className="min-h-[100dvh] bg-background text-foreground flex flex-col">
      <header className="border-b border-border px-6 h-14 flex items-center">
        <Link href="/" className="flex items-center gap-2 font-bold text-base">
          <div className="bg-primary text-primary-foreground p-1.5 rounded-md">
            <Gamepad2 className="h-4 w-4" />
          </div>
          GameForge
        </Link>
      </header>

      <div className="flex-1 flex items-center justify-center px-4 py-12">
        <div className="w-full max-w-sm space-y-4">
          {!preview && !previewError && (
            <div className="flex flex-col items-center gap-3 text-muted-foreground">
              <Loader2 className="h-6 w-6 animate-spin" />
              <p className="text-sm">Loading workspace…</p>
            </div>
          )}

          {previewError && (
            <Card className="border-destructive/40">
              <CardContent className="pt-6 flex flex-col items-center gap-3 text-center">
                <AlertCircle className="h-8 w-8 text-destructive" />
                <p className="font-semibold">Invalid invite link</p>
                <p className="text-sm text-muted-foreground">{previewError}</p>
                <Link href="/">
                  <Button variant="outline" className="mt-2">Go home</Button>
                </Link>
              </CardContent>
            </Card>
          )}

          {preview && !joined && (
            <Card>
              <CardContent className="pt-6 space-y-5">
                <div className="text-center space-y-1">
                  <div className="inline-flex h-14 w-14 items-center justify-center rounded-2xl bg-primary/10 text-primary mb-2">
                    <Gamepad2 className="h-7 w-7" />
                  </div>
                  <h1 className="text-xl font-bold">{preview.name}</h1>
                  <p className="text-sm text-muted-foreground flex items-center justify-center gap-1.5">
                    <Users className="h-3.5 w-3.5" />
                    {preview.memberCount} {preview.memberCount === 1 ? "member" : "members"}
                  </p>
                </div>

                {!isLoaded ? (
                  <div className="flex justify-center"><Loader2 className="h-5 w-5 animate-spin" /></div>
                ) : !isSignedIn ? (
                  <div className="space-y-2">
                    <p className="text-sm text-center text-muted-foreground">Sign in to join this workspace.</p>
                    <Link href={`/sign-in?redirect_url=${encodeURIComponent(window.location.pathname)}`}>
                      <Button className="w-full">Sign in to join</Button>
                    </Link>
                    <Link href={`/sign-up?redirect_url=${encodeURIComponent(window.location.pathname)}`}>
                      <Button variant="outline" className="w-full">Create account</Button>
                    </Link>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {joinError && (
                      <p className="text-sm text-destructive text-center">{joinError}</p>
                    )}
                    <Button className="w-full" onClick={join} disabled={joining}>
                      {joining ? <><Loader2 className="h-4 w-4 mr-2 animate-spin" /> Joining…</> : `Join ${preview.name}`}
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {joined && (
            <Card>
              <CardContent className="pt-6 flex flex-col items-center gap-3 text-center">
                <CheckCircle2 className="h-10 w-10 text-green-500" />
                <p className="font-semibold">You joined {preview?.name}!</p>
                <p className="text-sm text-muted-foreground">Redirecting to workspace…</p>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

