          let colorClass = "bg-transparent";
          let prefix = "  ";

          if (change.added) {
            colorClass = "bg-green-500/20";
            prefix = "+ ";
          } else if (change.removed) {
            colorClass = "bg-red-500/20";
            prefix = "- ";
          }

          return (
            <div key={i} className={`${colorClass} whitespace-pre-wrap`}>
              {change.value.split("\n").map((line: string, j: number) => (
                <div key={j}>
                  {prefix}{line}
                </div>
              ))}
            </div>
          );
        })}
      </div>
    </div>
  );
}

